(() => {
  const panel = document.querySelector('[data-send-queue]');
  if (!panel) throw new Error('the queue is not shown');
  if (panel.querySelectorAll('[data-queue-item]').length !== 1) throw new Error('the panel does not hold the held row');
  const row = [...document.querySelectorAll('button')].find(button => (button.innerText || '').trim().startsWith('打断并全部发送'));
  if (!row) throw new Error('no interrupt-all row');
  row.click();
  return 'interrupted with one held and one in the field';
})()

(() => {
  // The gap between the press and the run being reported over: the queue still
  // holds both sentences, so nothing has been handed over yet.
  const panel = document.querySelector('[data-send-queue]');
  if (!panel) throw new Error('the queue left before the run was reported over');
  const rows = panel.querySelectorAll('[data-queue-item]').length;
  if (rows !== 2) throw new Error('the interrupt did not carry the draft into the queue: ' + rows);
  const text = panel.innerText || '';
  if (!text.includes('顺便把图注也改成中文') || !text.includes('最后把配色换成低对比')) throw new Error('a held sentence is missing while stopping');
  return 'stopping, two rows still held';
})()

(async () => {
  const wanted = ['顺便把图注也改成中文', '最后把配色换成低对比'];
  const deadline = Date.now() + 15000;
  const rows = () => [...document.querySelectorAll('[data-message-id]')];
  while (Date.now() < deadline) {
    const hits = wanted.map(text => rows().filter(row => (row.innerText || '').includes(text)));
    if (hits.some(list => list.length > 1)) throw new Error('a queued sentence left as its own message');
    if (hits.every(list => list.length === 1)) {
      if (new Set(hits.map(list => list[0])).size !== 1) throw new Error('the two sentences did not travel as one message');
      if (document.querySelector('[data-send-queue]')) throw new Error('the queue outlived the interrupt');
      return 'one message carried both';
    }
    await new Promise(r => setTimeout(r, 200));
  }
  throw new Error('the queue never left the composer');
})()

