})()

(() => {
  // The phone keeps each conversation's draft across page loads, so a capture that
  // only adds text inherits what the previous one typed. Clear it first.
  const box = document.querySelector('[aria-label="给 FutureOS 发消息"]');
  box.focus();
  const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
  setter.call(box, '');
  box.dispatchEvent(new Event('input', { bubbles: true }));
  return 'draft cleared';
})()

(() => {
  const choose = document.querySelector("[aria-label='选择如何处理这条消息']");
  if (!choose) throw new Error('a draft during a run offers no queue choice');
  if (document.querySelector("[aria-label='停止']")) throw new Error('a draft during a run still offers only Stop');
  return 'choice offered';
})()

(() => {
  const body = document.body.innerText || '';
  for (const text of ['加入发送队列', '打断后发送', '当前回复结束后自动发送']) {
    if (!body.includes(text)) throw new Error('the sheet is missing: ' + text);
  }
  return 'sheet rows present';
})()

