(() => {
  const panel = document.querySelector('[data-testid="send-queue"]');
  if (!panel) throw new Error('the refused queue is not shown');
  if (!(panel.innerText || '').includes('顺便把图注也改成中文')) throw new Error('the refused message was dropped');
  if (!panel.querySelector('[aria-label="重试"]')) throw new Error('the panel offers no retry');
  const edit = panel.querySelector('[aria-label="修改队列中的消息"]');
  if (!edit) throw new Error('the refused row cannot be edited');
  edit.click();
  return 'refused, still held, opened for editing';
})()

(() => {
